// Despliegue en otra Región con una AMI. Corrige su defecto principal.
export const despliegue = {
  amiOrigen: { id: "ami-origen", region: "region-a", arquitectura: "x86" },
  copias: [],
  lanzamiento: {
    region: "region-b",
    ami: "ami-origen",
    instancia: { familia: "compute", arquitectura: "x86" },
  },
};

solution.code:
export const despliegue = {
  amiOrigen: { id: "ami-origen", region: "region-a", arquitectura: "x86" },
  copias: [{ id: "ami-copia-b", region: "region-b", origen: "ami-origen", arquitectura: "x86" }],
  lanzamiento: {
    region: "region-b",
    ami: "ami-copia-b",
    instancia: { familia: "compute", arquitectura: "x86" },
  },
};

spec.code:
const catalogo = [despliegue.amiOrigen, ...despliegue.copias];
const usada = catalogo.find((a) => a.id === despliegue.lanzamiento.ami);
assert.ok(usada, "la AMI del lanzamiento debe existir");
assert.strictEqual(usada.region, despliegue.lanzamiento.region, "una AMI es específica de una Región");

const catalogo = [despliegue.amiOrigen, ...despliegue.copias];
const usada = catalogo.find((a) => a.id === despliegue.lanzamiento.ami);
assert.ok(usada, "la AMI del lanzamiento debe existir");
assert.strictEqual(usada.arquitectura, despliegue.lanzamiento.instancia.arquitectura);

assert.ok(despliegue.copias.length >= 1, "debe haber al menos una copia");
for (const copia of despliegue.copias) {
  assert.strictEqual(copia.origen, "ami-origen");
  assert.strictEqual(copia.arquitectura, "x86");
}
